import {
  registerAll,
  VSeed,
  Builder,
  isPivotChart,
  isVChart,
  isPivotTable,
  isTable,
  zVSeed,
  ColorIdEncoding,
  DATUM_HIDE_KEY,
} from '@visactor/vseed'

registerAll()
register.chartModule('vchart', VChart)

const SimpleVSeedRender = (props: { vseed: VSeed }) => {
  const { vseed } = props
  const ref = useRef<HTMLDivElement>(null)
  const builderRef = useRef<Builder>()
  const dark = useDark()
  const selectedDimValueRef = useRef<string[]>([])
  useEffect(() => {
    let cleanup: (() => void) | undefined

    const initChart = async () => {
      if (!ref.current) {
        return
      }
      const theme = dark ? 'dark' : 'light'
      const builder = Builder.from(vseed.theme ? vseed : { ...vseed, theme })

      // If there is dynamicFilter code, need to prepare first before building
      await builder.prepare()
      let spec = builder.build()

      console.log('final spec = ', spec)
      console.log('builder', builder)
      console.log('builder performance', builder.performance)

      builderRef.current = builder
      if (isPivotChart(vseed)) {
        const tableInstance = new PivotChart(ref.current, spec)

        tableInstance.on('legend_item_click', (args) => {
          console.log('LEGEND_ITEM_CLICK', args)
          tableInstance.updateFilterRules([
            {
              filterKey: ColorIdEncoding,
              filteredValues: args.value,
            },
          ])
        })
        tableInstance.on('legend_change', (args) => {
          const maxValue = args.value[1]
          const minValue = args.value[0]

          if (vseed.chartType === 'heatmap') {
            tableInstance.updateFilterRules([
              {
                filterFunc: (record) => {
                  const value = record[record[ColorIdEncoding]]
                  const isShow = value >= minValue && value <= maxValue

                  record[DATUM_HIDE_KEY] = !isShow

                  return true
                },
              },
            ])
          } else {
            tableInstance.updateFilterRules([
              {
                filterFunc: (record) => {
                  const value = record[record[ColorIdEncoding]]
                  if (value >= minValue && value <= maxValue) {
                    return true
                  }
                  return false
                },
              },
            ])
          }
        })
        window.pivotChart = tableInstance
        cleanup = () => tableInstance.release()
      } else if (isVChart(vseed)) {
        const vchart = new VChart(spec, { dom: ref.current })
        vchart.renderSync()

        vchart.on('brushEnd', (e) => {
          console.log(e)
        })

        window.vchart = vchart
        cleanup = () => vchart.release()
      } else if (isTable(vseed)) {
        const tableInstance = new ListTable(ref.current, spec)
        window.table = tableInstance
        cleanup = () => tableInstance.release()
      } else if (isPivotTable(vseed)) {
        const tableInstance = new PivotTable(ref.current, spec)

        window.table = tableInstance
        cleanup = () => tableInstance.release()
      }
    }

    initChart()

    return () => {
      cleanup?.()
    }
  }, [vseed, dark])

  return (
    <div
      ref={ref}
      style={{ height: 600, width: '100%' }}
      onClick={() => {
        console.group(`selected ${vseed.chartType}`)
        console.log('builder', builderRef.current)
        console.log('spec', builderRef.current.spec)
        console.log('vseed', builderRef.current.vseed)
        console.log('advancedVSeed', builderRef.current.advancedVSeed)
        console.groupEnd()
      }}
    >
      {' '}
    </div>
  )
}

export default Demo
```

This example demonstrates combining `useVBI` with `useVSeed`.

## Dependencies

- Packages: `@visactor/vbi-react`, `@visactor/vbi`, `@visactor/vseed`, `react`
- Props: requires an initialized `VBIChartBuilder` (with a bound connector)

## Code Snippet

```tsx



export function BasicHooksDemo({ builder }: { builder: VBIChartBuilder }) {
  const { dsl } = useVBI(builder)
  const { vseed, loading, error, refetch } = useVSeed(builder, { debounce: 100 })

  if (error) {
    return <button onClick={() => void refetch()}>Retry: {error.message}</button>
  }

  if (loading || !vseed) {
    return <div>Loading...</div>
  }

  return (
    <div>
      <h4>chartType: {dsl.chartType}</h4>
      <pre>{JSON.stringify(vseed, null, 2)}</pre>
    </div>
  )
}
```

## Expected Behavior

- When the builder changes, `dsl` and `vseed` update in sync.
- Shows `Loading...` on first load or when updating; allows manual retry on failure.
- On success, displays the current `chartType` and the latest VSeed JSON.

This example demonstrates the mutation entry points for `useWhereFilter` and `useHavingFilter`.

## Dependencies

- Packages: `@visactor/vbi-react`, `@visactor/vbi`, `react`
- Props: `builder` should contain at least `region` and `sales` fields for demonstrating Where/Having mutations

## Code Snippet

```tsx



export function FilterDemo({ builder }: { builder: VBIChartBuilder }) {
  const { whereFilter, mutateWhereFilter, clearWhereFilter } = useWhereFilter(builder)
  const { havingFilter, mutateHavingFilter, clearHavingFilter } = useHavingFilter(builder)

  return (
    <div style={{ display: 'grid', gap: 8 }}>
      <button
        onClick={() =>
          mutateWhereFilter((where) => {
            where.add('region', (node) => node.setOperator('eq').setValue('East'))
          })
        }
      >
        Add Where Condition
      </button>
      <button
        onClick={() =>
          mutateHavingFilter((having) => {
            having.add('sales', (node) => node.setAggregate({ func: 'sum' }).setOperator('gt').setValue(1000))
          })
        }
      >
        Add Having Condition
      </button>
      <button onClick={clearWhereFilter}>Clear Where</button>
      <button onClick={clearHavingFilter}>Clear Having</button>
      <pre>{JSON.stringify({ whereFilter, havingFilter }, null, 2)}</pre>
    </div>
  )
}
```

## Expected Behavior

- After clicking buttons, Where/Having conditions are appended to the builder's filter tree.
- The clear buttons immediately remove the corresponding filter conditions.
- The JSON at the bottom can be used to confirm the current filter DSL structure.

This example demonstrates `BuilderLayout` + `FieldPanel` + `ChartRenderer` + `ChartTypeSelector`.

## Dependencies

- Packages: `@visactor/vbi-react/components`, `@visactor/vbi`, `react`
- Props: `builder` should have available dimension/measure fields for `FieldPanel` add/remove demos

## Code Snippet

```tsx



export function LayoutDemo({ builder }: { builder: VBIChartBuilder }) {
  return (
    <BuilderLayout
      topBar={<ChartTypeSelector builder={builder} />}
      leftPanel={
        <FieldPanel
          builder={builder}
          dimensionOptions={[{ label: 'Region', value: 'region' }]}
          measureOptions={[{ label: 'Sales', value: 'sales' }]}
        />
      }
      main={<ChartRenderer builder={builder} debounce={100} />}
    />
  )
}
```

## Expected Behavior

- Top bar: switch chart type; Left panel: add/remove dimensions/measures; Main area: chart DSL preview.
- Main area auto-refreshes after field operations — no manual trigger needed.
- On build failure, `ChartRenderer` shows a default error message and retry button.

